'use strict';
const R=RiskModel;
const RISK_CONTEXT={
 DXY:['美元偏强可能收紧全球美元流动性，并压制风险偏好。','核对美债利率与人民币是否同向；美元上涨不必然导致A股下跌。'],
 CNH:['USD/CNH上升代表离岸人民币走弱，影响外资风险偏好、进口成本及汇兑。','出口公司的外币收入与进口设备支出方向不同，需结合净敞口。'],
 US10Y:['美债收益率上行抬升全球折现率，科技长久期估值通常更敏感。','区分增长预期上修与通胀/期限溢价；收益率变化用bp，不称债券收益。'],
 DJI:['道指观察美国大型蓝筹与经济周期风险。','与纳指分化时，检查行业轮动，不能用道指替代科技景气。'],
 IXIC:['纳斯达克综合指数反映美国科技与成长股整体风险偏好。','需与SOXX、QQQ及公司经营交叉验证；成分存在重合。'],
 N225:['日经225观察日本风险偏好、半导体设备及日元相关传导。','本币指数未计汇率；关注设备供应链、出口限制及订单。'],
 KOSPI:['韩国综合指数对存储与电子周期较敏感，可辅助观察DRAM链。','综合指数不等于存储价格；长鑫科技仍需产品价格与扩产证据。'],
 SOX:['SOX为纳斯达克发布的PHLX半导体行业价格指数，用于观察半导体设计、制造与设备链交易风险。','与SOXX ETF的编制基准和成分权重不同；二者不互相替代，合计权重22%（SOX 12%、SOXX 10%）。'],
 usSOXX:['SOXX作为美股半导体价格代理，连接芯片、设备与制造链风险。','对中芯国际/长鑫科技观察行业共振；ETF涨跌不能替代利用率和现金流。'],
 usQQQ:['QQQ跟踪纳指100，观察大型成长股折现率及AI资本开支预期。','QQQ权重上调至14%，强化大型科技压力传导；与纳指、SOX/SOXX仍有相关性重叠。'],
 hkHSTECH:['恒生科技观察离岸中国科技风险偏好、流动性与盈利预期。','与A股科创50业务结构不同，观察相对变化，不机械同步。'],
 A50:['富时中国A50观察中国大盘股离岸定价与风险偏好。','本项是现货指数，不是A50期货；注意时区与期货基差。'],
 GOLD:['黄金连续期货同时受避险、实际利率与美元影响。','仅把剧烈变动与波动计为跨资产压力；不把上涨统一视为利空。'],
 SILVER:['白银同时具有贵金属与工业需求属性，波动通常较大。','结合黄金和工业周期；连续合约换月会影响长窗口变化。'],
 BTC:['比特币观察24小时高波动风险资产的杠杆与流动性压力。','周末仍交易；与A股传导关系不稳定，不直接映射涨跌。']
};
function riskState(r){return !E.valid(r.score)||r.coverage<.6?['证据不足','warn']:r.score>=80?['高关注','danger']:r.score>=60?['偏高','warn']:r.score>=30?['需关注','neutral']:['相对较低','good']}
function riskNumber(r){return E.valid(r.score)&&r.coverage>=.6?num(r.score,1):'—'}
function riskBadge(r){const [label,tone]=riskState(r);return `<span class="risk-badge">${pill(label,tone)} <b>${riskNumber(r)}</b><small>/100</small></span>`}
function riskCoverage(r){return `<div class="risk-coverage"><span>有效权重 ${num(r.coverage*100,0)}%</span><span>缺失边界 ${num(r.low,0)}–${num(r.high,0)}</span></div><div class="risk-track"><i style="width:${Math.round(r.coverage*100)}%"></i></div>`}
function riskCard(n,label,r,text,anchor){return `<a class="risk-card" href="#${anchor}" onclick="event.preventDefault();document.getElementById('${anchor}').scrollIntoView({behavior:'smooth',block:'start'})"><div class="risk-card-head"><span>0${n} / ${label}</span>${pill(riskState(r)[0],riskState(r)[1])}</div><strong class="risk-number">${riskNumber(r)}<small>/ 100</small></strong><p>${text}</p>${riskCoverage(r)}</a>`}
function riskPartsTable(parts){return `<div class="table-wrap"><table class="wrap-table"><thead><tr><th>分项</th><th>名义权重</th><th>关注分</th><th>有效覆盖</th><th>规则 / 证据时间</th></tr></thead><tbody>${parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${num(p.weight,1)}</td><td>${E.valid(p.score)?num(p.score,1):'缺失'}</td><td>${E.valid(p.score)?num((p.coverage??1)*100,0)+'%':'0%'}</td><td>${esc(p.reason||'本层分数按下层有效权重传递')} ${esc(p.date||'')}</td></tr>`).join('')}</tbody></table></div>`}
function riskSnapshot(){const d=data(),ext=R.globalRisk(d.external,d.geopolitics),dom=R.domesticRisk(d.instruments,BENCH_CODES,ext),watch=WATCH_CODES.map(code=>{const a=byCode(code),parent=(a.market||'CN')==='CN'?dom:R.regionalRisk(ext,a.market);return {...R.watchRisk(d.instruments[code],a,parent),parentRisk:parent,parentLabel:({CN:'A股',HK:'港股',US:'美股'})[a.market||'CN']}}),group=R.aggregate(watch.map(r=>({...r,name:r.asset.name,weight:1})));return {d,ext,dom,watch,group}}
function externalChange(x,n){const r=x.returns?.[n];if(!E.valid(r?.value))return `<span class="muted" title="${esc(r?.reason||'历史不足或未接入')}">— 历史不足</span>`;return `<strong>${r.value>0?'+':''}${num(r.value)}${r.unit==='bp'?' bp':'%'}</strong><small class="table-sub">${esc(r.start)} → ${esc(r.end)}</small>`}
function externalRead(x){const m=x.model||R.technical(x.history,x.kind),s=RISK_CONTEXT[x.symbol];return `<p>${esc(s?.[0]||'辅助观察海外产业链风险偏好，不计入外围总分。')}</p><p class="muted">${x.kind==='yield'&&x.history?.length>20?`20日变动 ${num((x.history.at(-1).close-x.history.at(-21).close)*100)} bp；`:E.valid(m.ret20)?`20日${change(m.ret20)}，`:''}${x.kind!=='yield'&&E.valid(m.drawdown)?`近60日高点回撤${num(m.drawdown)}%；`:''}${esc(s?.[1]||'结合经营披露与国内相对走势验证。')}</p>${x.error||x.history_error?`<small class="risk-warning">本次${x.history_error?'历史':''}取数失败${x.retained||x.retained_history?'，保留上次可用数据':''}：${esc(x.error||x.history_error)}</small>`:''}`}
function riskExternalTable(assets){return `<div class="table-wrap"><table class="wrap-table risk-table"><thead><tr><th>外围标的 / 权重</th><th>最近价格 / 单位</th><th>关注分 / 覆盖</th><th>风险解读与产业传导</th><th>日期 / 来源</th></tr></thead><tbody>${assets.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.ticker||x.symbol)} · ${x.weight}%</small></td><td>${num(x.price,x.symbol==='CNH'?4:2)}<small class="table-sub">${esc(x.unit||'—')}</small></td><td>${riskBadge(x.model)}<small class="table-sub">有效权重 ${num(x.model.coverage*100,0)}%</small></td><td class="risk-explain">${externalRead(x)}</td><td>${esc(x.history_as_of||'未返回')}<small class="table-sub">${esc(x.timezone||'日频')}</small>${x.url?sourceLink(x.url,'行情'):''}${x.history_url?' · '+sourceLink(x.history_url,'历史'):''}${x.provisional?'<small class="table-sub">末根为盘中快照，可修订</small>':''}</td></tr>`).join('')}</tbody></table></div>`}
function geopoliticalPanel(geo){const fresh=R.fresh(geo?.as_of,14);return `<div class="grid-two risk-geo">${['politics','war'].map(kind=>{const item=(geo?.items||[]).find(x=>x.kind===kind),r=R.aggregate([R.leaf('',1,fresh?item?.score:null)]),war=kind==='war';return panel(war?'B2 · 战争 / 冲突风险':'B1 · 政治 / 地缘风险',`<div class="panel-body">${riskBadge(r)}<p class="risk-description">${war?'行动类新闻增多，可能通过能源、航运、保险和交付扰动传导。':'威胁类新闻增多，可能通过出口许可、投资审查和风险溢价传导。'}这是模型解释，不能据此确认具体战况或政策现状。</p><div class="definition-row"><span>${esc(item?.field||'GPR子项')} · 30日均值</span><strong>${num(item?.value30)}</strong></div><p class="small muted">${esc(geo?.as_of||'尚未抓取')} · 近3年${item?.baseline_count||0}个有效滚动均值 · 权重10%。政治广义风险未被新闻指数完整覆盖。</p>${war?`<div class="risk-source-event"><strong>已核实背景 · 2026-10-15</strong><p>联合国安理会声明涉及红海商业航运、能源设施与地区升级风险。对科技链需验证运价、运输路线及交付影响。</p>${sourceLink('https://mandates.un.org/mandate/S/PRST/2026/4?subject=Red+Sea','联合国声明 S/PRST/2026/4')}</div>`:`<div class="risk-source-event"><strong>历史政策背景 · 2026-01-13</strong><p>美国BIS曾调整部分对华半导体出口许可审查政策。此条仅作历史背景；当前许可范围与适用性须再查官方更新。</p>${sourceLink('https://media.bis.gov/press-release/department-commerce-revises-license-review-policy-semiconductors-exported-china','BIS原文')}</div>`}<small class="muted">背景核对日2026-11-01；不参与数值评分，不自动更新战况。GPR日频、每周更新、允许回修；超过14天停止计分。</small>${geo?.error?`<p class="risk-warning">GPR本次刷新失败：${esc(geo.error)}</p>`:''}</div>`)}).join('')}</div><div class="panel-note">量化口径：威胁/行动子项的30日均值，在近1095日有效滚动均值中计算历史分位（0–100）；至少252个样本。分位高表示新闻压力处于历史高位，不是政治事件或战争的发生概率。${sourceLink(geo?.url||'https://www.matteoiacoviello.com/gpr.htm','GPR官方数据与方法')} · Caldara & Iacoviello (2022), CC BY 4.0。</div>`}
function riskOverview(){const {d,ext,dom,watch,group}=riskSnapshot();return title('风险总览','从全球压力到A股结构，再到每一只自选。分数越高，需关注的风险越多。',button('查看评分方法',"document.getElementById('risk-method').scrollIntoView({behavior:'smooth'})",false,'info'))+`<div class="risk-hero"><div><span class="risk-eyebrow">RISK TRANSMISSION / 风险传导</span><h2>把风险放在同一张地图上</h2><p>外围分项加权 → A股本地70% + 外围30% → 自选自身75% + 对应市场25%</p></div><div class="risk-model-tag">研究模型 v1.1<small>非概率 · 权重尚未实证校准</small></div></div><div class="risk-cards">${riskCard(1,'外围风险',ext,'15类跨市场资产80% + 政治10% + 战争10%','risk-external')}${riskCard(2,'A股指数风险',dom,'六ETF本地风险70% + 外围风险30%','risk-domestic')}${riskCard(3,'自选风险',group,WATCH_CODES.length+'只自选综合风险等权观察；非账户持仓风险','risk-watch')}</div><p class="risk-caption">分数按已知有效权重暂估；有效权重不足60%时隐藏点分。边界假设缺失项分别为0/100，不是置信区间。各市场日频时间不同，均以行内日期为准。</p>${isDemo()?notice('当前为合成演示：A股分数仅演示规则；外围及GPR未伪造样本。请连接本地数据后刷新。'):''}<section id="risk-external" class="risk-section">${panel('01 · 外围风险',`<div class="panel-body risk-section-intro"><div><h3>A · 跨市场资产压力</h3><p>美元/人民币/美债15% · 海外股票50%（纳指8%、SOX 12%、SOXX 10%、QQQ 14%） · 离岸中国8% · 贵金属/比特币7%。股指用下行、趋势和波动；汇率/利率以上行压力；贵金属用绝对冲击。</p></div>${riskBadge(ext)}</div>${globalAssetCards(ext.assets)}${geopoliticalPanel(d.geopolitics)}`)}</section><section id="risk-domestic" class="risk-section">${panel('02 · A股指数风险',`<div class="panel-body risk-section-intro"><div><h3>六类ETF等权，保留风格差异</h3><p>六ETF本地分 ${riskNumber(dom.local)} ×70% + 外围分 ${riskNumber(ext)} ×30%；缺失有效权重逐层折减。全部为ETF价格代理，未计分红总回报。</p></div>${riskBadge(dom)}</div>${benchmarkCards(null,dom.rows)}<div class="panel-body">${finding('科技链的传导需要二次确认',`${marketConclusion().label}。SOX、SOXX/韩国市场用于观察半导体风险，QQQ/纳指用于观察AI与成长风险，人民币和美债用于观察流动性与折现率。`,'结合六ETF相对走势、公司订单、利用率及现金流；模型加权反映研究关注程度，不代表统计因果关系。')}</div><details class="risk-details"><summary>展开本层权重及覆盖</summary>${riskPartsTable(dom.parts)}</details>`)}</section><section id="risk-watch" class="risk-section">${panel('03 · 自选风险',`<div class="panel-body"><p class="risk-description">每只标的：自身七维75% + 对应市场风险25%（A股六ETF、港股离岸中国代理、美股科技及宽基代理）。自身权重为趋势20%、经营/成分20%、估值10%、资金10%、波动15%、回撤15%、治理事件10%。ETF改用成分集中度、同日净值及申赎口径。</p></div><div class="risk-watch-grid">${watch.map(x=>`<article class="risk-stock"><div class="risk-stock-head"><div><button class="stock-link" onclick="setAsset('${x.code}','research')">${x.asset.name}</button><small>${x.code} · ${x.asset.industry}</small></div>${riskBadge(x)}</div>${riskCoverage(x)}<p>${x.price.date?'价格截至 '+esc(x.price.date):'价格证据不足'}${E.valid(x.price.ret20)?' · 20日 '+change(x.price.ret20):''}</p><div class="risk-contributors"><span>自身 ${riskNumber(x.local)} ×75%</span><span>${x.parentLabel} ${riskNumber(x.parentRisk)} ×25%</span></div><details class="risk-details"><summary>七维评分、缺失项与依据</summary>${riskPartsTable(x.local.parts)}<div class="panel-note">${provenance(ctx(x.code))} ${button('打开七维研究',`setAsset('${x.code}','research')`,false)}</div></details></article>`).join('')}</div>`)}</section>${riskMethod()}`}
function riskMethod(){return `<section id="risk-method" class="risk-section">${panel('评分方法与适用边界',`<div class="panel-body"><h3>0–100关注分，不是亏损概率</h3><p class="risk-description">0–30相对较低，30–60需关注，60–80偏高，80–100高关注。阈值与权重均为可审查的研究假设，尚未经过样本外校准；本页实时快照评分不回填历史回测，也不自动下单。</p><details class="risk-details"><summary>资产评分公式与时效</summary><div class="risk-method-copy"><p>股票/ETF：趋势30%（低于MA20与MA60各50分）+20日下行25%（跌15%封顶100）+近60日最高收盘回撤25%（回撤25%封顶）+20日收益标准差年化波动20%（60%封顶；比特币100%）。年化天数股票252、比特币365。</p><p>美元/人民币/利率：上行趋势50%（高于MA20、MA60各50分）+20日上行压力30%（美元/人民币升5%，美债升50bp封顶）+波动20%（年化20%或利率日变化标准差10bp封顶）。人民币报价为USD/CNH，数值上升代表人民币走弱。黄金/白银：20日绝对涨跌冲击50%（15%封顶）+年化波动50%（60%封顶）。</p><p>自身七维与外围资产模型的权重分别计算。自选经营项内部：收入下降压力30%（降30%封顶）、现金兑现50%（正净利条件下，1−经营现金/净利）、负债20%（资产负债率80%封顶）。资金项近5条大单净流出5亿元封顶。ETF前十持仓占净值直接映射集中关注分；同日净值偏离3%封顶。负净利的现金兑现不适用，保留缺失。</p><p>价格超过7个自然日（比特币2日）、财报披露/ETF报告期超过220日、GPR超过14日，停止计入相应维度。收盘前价格可变，图中及表内标明盘中。估值缺同行/历史分位、治理缺原文影响判断时保持缺失；不把没有公告视为零风险。</p></div></details><details class="risk-details"><summary>缺失权重如何层层传递</summary><div class="risk-method-copy"><p>有效权重=名义权重×下层覆盖率；暂估分=Σ(有效权重×分项分)/Σ有效权重。覆盖率=Σ有效权重/Σ名义权重。上层使用相同公式继续传播，不将不完整的外围分视作完整证据。</p><p>缺失边界下限=Σ(有效权重×分项分)/总权重，上限=下限+100×缺失比例。边界宽说明证据不足，不用于构造虚假的精确结论。外围与A股权重有相关性；本模型尚未估计跨市场贝塔与滞后影响。</p></div></details></div>`)}</section>`}
function externalV6(){const rows=data().external||[];return `<div class="grid-two">${panel('外围表现与产业传导',`<div class="panel-body">${finding('把短期情绪与中长期变化分开','最近60日与250日按相应标的有效日频观察值计算：末值÷60/250个间隔前价格−1；需要61/251条日线。不填补停牌或节假日，不将年内收益当250日收益。','半导体观察SOXX及美光/台积电，算力互联观察QQQ/英伟达/博通；国内公司仍需订单、盈利和经营现金流证据。')}${button('查看完整风险传导',"go('overview')",true)}</div>`)}${panel('比较口径',`<div class="panel-body"><p class="risk-description">美债收益率使用基点变化；黄金/白银为连续期货价格代理，包含换月影响。ETF与股指为价格变化，不含现金分红总回报；美元报价未换算人民币。比特币包含周末观察值，跨市场窗口的日历长度不同。末根若盘中将随刷新变化。</p></div>`)}</div><section class="panel"><div class="table-wrap"><table class="wrap-table external-returns"><thead><tr><th>外围标的</th><th>价格</th><th>最近一日</th><th>最近60日收益 / bp</th><th>最近250日收益 / bp</th><th>观察日期 / 来源</th><th>解读</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.ticker||x.symbol)}</small></td><td>${num(x.price)}<small class="table-sub">${esc(x.unit||'')}</small></td><td>${change(x.change)}</td><td>${externalChange(x,'60')}</td><td>${externalChange(x,'250')}</td><td>${esc(x.history_as_of||x.timestamp||'—')}<small class="table-sub">${x.history?.length||0}条日线 · ${esc(x.timezone||'')}</small>${pill(R.fresh(x.history_as_of,x.kind==='crypto'?2:7)?(x.provisional?'盘中快照':'日频快照'):'缺失 / 过期',R.fresh(x.history_as_of,x.kind==='crypto'?2:7)?'good':'warn')} ${sourceLink(x.url,'来源')}</td><td class="risk-explain">${externalRead(x)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">尚无外围数据。请刷新本地行情；演示模式不补造外围历史。</td></tr>'}</tbody></table></div></section>`}
function strategyExplanation(){return panel('策略解释 · 三因子增强与六ETF走弱过滤',`<div class="panel-body"><div class="grid-two strategy-help"><div><div class="chip-line">${pill('三因子增强',bt.enhanced?'good':'neutral')}${pill(bt.enhanced?'当前已启用':'当前未启用','neutral')}</div><h3>给金叉增加量价与资金验证</h3><p>基础信号来自三重EMA：买入用N=3/3，卖出用N=5/5。增强模式用资金流入、量价背离、布林带宽扩张共同打分；A/B级买入分数低于−0.5则跳过。资金缺失时不凑分，保留基础信号。</p><details class="risk-details"><summary>展开三因子公式与附加信号</summary><p>资金因子 M=clip(当日大单净额÷5亿元, −2, 2)，权重40%；量价因子 D 比较5日前：价涨量缩=−1、价跌量缩=+1、价量齐升=0.5，其余=0，权重30%；带宽扩张 X=当前布林带宽÷此前20日平均带宽，权重30%。布林带宽=4×20日收盘标准差÷MA20。</p><div class="risk-formula">Score = 0.4M + 0.3D + 0.3(X−1)×2</div><p>增强还可能提前生成信号：净流入&gt;2亿元、POS≥0.8、量比≥1、|SHORTL−MIDL|&lt;6时提前买入；N3死叉且净流出&lt;−3亿元时提前卖出。POS是收盘在日内高低区间的位置。以上为本版研究阈值，波动扩张既可能伴随上涨也可能伴随下跌，分高不保证盈利。</p></details></div><div><div class="chip-line">${pill('六ETF走弱过滤',bt.marketGate?'good':'neutral')}${pill(bt.marketGate?'当前已启用':'当前未启用','neutral')}</div><h3>先看市场环境，再决定是否新增模拟</h3><p>沪深300ETF、中证A500ETF、中证500ETF、中证1000ETF、创业板ETF、科创50ETF，分别用历史信号日收盘价比较当日MA10。至少4/6低于MA10时，跳过该笔新增买入；卖出继续按原规则执行。任一ETF缺历史或MA10，也跳过新增买入。</p><details class="risk-details"><summary>展开回测时序与适用边界</summary><p>使用信号当日以前已确认收盘的ETF数据，禁止拿今天的市场状态回填历史。过滤是暂停新增模拟，不是自动卖出或按级减仓；不同于技能原始四指数≥3只走弱版本。</p><p>两个开关可独立比较。信号收盘后形成订单，次日开盘或按信号收盘价±限价模拟；未穿价保留未成交，不事后回到同日开盘追单。绩效含所设成本与滑点。风险总览新评分仅供当前研究，不会自动改变历史策略。</p></details></div></div><p class="small muted">基础A/B使用相同研究仓位，C级跳过，卖出统一平仓。当前开关状态已与左侧研究参数同步；改变后自动重算订单、信号及图表。六ETF过滤仅用于A股；港美股按各自市场日期、交易币种和1股研究单位独立回测。</p></div>`,'','panel-space')}
window.overview=riskOverview;window.externalV4=externalV6;
